const fail = (ms, message) =>
  new Promise((resolve, reject) => setTimeout(() => reject(new Error(message)), ms));

async function first() {
  try {
    return fail(10, "first broke");
  } catch {
    return "first caught it";
  }
}

async function second() {
  try {
    return await fail(30, "second broke");
  } catch {
    return "second caught it";
  }
}

first().then(
  (value) => console.log(value),
  (error) => console.log("rejected: " + error.message)
);
second().then((value) => console.log(value));
